<script setup>
import { reactive, ref, onMounted, onUnmounted } from 'vue';
import { api, action, date } from '../api';
import { ElMessage } from 'element-plus';
import PageState from '../components/PageState.vue';
const form=reactive({kind:'WEB',url:'',branch:'',path:'',organize:true}),jobs=ref([]),busy=ref(false),error=ref(''),loading=ref(true);
let alive=true,timer,polling=false;
const labels={QUEUED:'排队中',RUNNING:'正在采集',SUCCEEDED:'已导入',UNCHANGED:'内容未变化',FAILED:'采集失败',CANCELLED:'已取消'};
async function load(){if(polling)return;polling=true;try{const data=await api('/api/imports');if(alive){jobs.value=data;error.value='';}}catch(e){if(alive)error.value=e.message;}finally{if(alive)loading.value=false;polling=false;}}
async function submit(){if(!form.url.trim())return;busy.value=true;await action(async()=>{await api('/api/imports',{method:'POST',body:form});ElMessage.success('采集任务已加入队列');form.url='';await load();});busy.value=false;}
async function command(id,op){await action(async()=>{await api(`/api/imports/${id}/${op}`,{method:'POST'});await load();});}
onMounted(()=>{load();timer=setInterval(load,3000);});onUnmounted(()=>{alive=false;clearInterval(timer);});
</script>
<template><section><div class="page-heading"><div><h1>采集知识</h1><p>从网页或代码仓库创建 Book。来源与快照随内容保存，后续可重新采集。</p></div><RouterLink to="/admin/books/new" class="text-link">上传本地文件 →</RouterLink></div><div class="knowledge-split"><form class="knowledge-panel collection-form" @submit.prevent="submit"><h2>添加来源</h2><el-radio-group v-model="form.kind" aria-label="采集类型"><el-radio-button value="WEB">网页正文</el-radio-button><el-radio-button value="REPO">代码仓库</el-radio-button></el-radio-group><label for="collect-url">{{form.kind==='WEB'?'网页地址':'GitHub / GitLab 项目地址'}}</label><el-input id="collect-url" v-model="form.url" type="url" required maxlength="2000" :placeholder="form.kind==='WEB'?'https://example.com/article':'https://github.com/owner/project'"/><template v-if="form.kind==='REPO'"><label for="collect-branch">分支或提交（可选）</label><el-input id="collect-branch" v-model="form.branch" maxlength="128" placeholder="留空使用默认分支"/><label for="collect-path">只导入子目录（可选）</label><el-input id="collect-path" v-model="form.path" maxlength="255" placeholder="例如 src 或 docs"/></template><el-checkbox v-model="form.organize">自动分类并生成标签</el-checkbox><p class="muted">{{form.kind==='WEB'?'提取可直接访问的网页正文。需要登录或 JavaScript 渲染的页面可改用文件上传。':'保存仓库当前快照、目录和可读代码，不运行项目。大仓库请指定子目录；私有仓库需在服务端配置对应令牌。'}}</p><el-button type="primary" native-type="submit" :loading="busy">开始采集</el-button></form><div class="knowledge-panel"><h2>采集记录</h2><p class="muted">同一来源再次提交会更新已有 Book；原文未变化时跳过索引。默认保留最近 100 条记录。</p><PageState :loading="loading" :error="error" :empty="!jobs.length" title="还没有采集来源" description="添加一个网页或项目地址，任务完成后可直接打开阅读。" @retry="load"><ol class="import-timeline"><li v-for="job in jobs" :key="job.id"><span class="status" :class="job.status.toLowerCase()">{{labels[job.status]}}</span><strong>{{job.kind==='WEB'?'网页':'仓库'}}</strong><span class="time">{{date(job.updatedAt)}}</span><p class="source-url">{{job.sourceUrl}}</p><p v-if="job.error" class="error">{{job.error}}</p><div class="row-actions"><RouterLink v-if="job.bookId" :to="`/books/${job.bookId}`">打开 Book</RouterLink><button v-if="job.status==='FAILED'" @click="command(job.id,'retry')">重试</button><button v-if="['QUEUED','RUNNING'].includes(job.status)" @click="command(job.id,'cancel')">取消</button></div></li></ol></PageState></div></div></section></template>
